  makeShot(shot) {
    const material = new THREE.MeshBasicMaterial({ color: shot.color });
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(Math.max(2, shot.r * .72), 10, 8), material);
    const glow = new THREE.PointLight(shot.color, 8, 24, 2);
    mesh.add(glow);
    this.scene.add(mesh);
    return mesh;
  }

  makeParticle(particle) {
    const mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(Math.max(.7, particle.size * .5), 0), new THREE.MeshBasicMaterial({ color: particle.color, transparent: true, depthWrite: false }));
    this.scene.add(mesh);
    return mesh;
  }

  syncEntities(entities, cache, factory, visible) {
    const active = new Set();
    for (const entity of entities) {
      if (!visible(entity)) continue;
      active.add(entity);
      let mesh = cache.get(entity);
      if (!mesh) { mesh = factory.call(this, entity); cache.set(entity, mesh); }
      mesh.visible = true;
      mesh.position.set(entity.x, 0, entity.y);
    }
    for (const [entity, mesh] of cache) mesh.visible = active.has(entity);
  }

  render(world, elapsed, dt, shake = 0) {
    const { player, enemies, loot, shots, particles, floating, shrine } = world;
    const time = elapsed || 0;
    this.player.position.set(player.x, 0, player.y);
    this.player.rotation.y = Math.PI / 2 - player.face;
    this.player.position.y = Math.sin(time * 7) * .35;
    this.player.visible = player.invuln <= 0 || Math.floor(time * 18) % 2 === 0;
    const swing = player.attack > 0 ? Math.sin((player.attack / .31) * Math.PI) : 0;
    this.player.rotation.z = -swing * .22;

    this.syncEntities(enemies, this.entityMeshes, this.makeEnemy, entity => entity.alive);
    for (const entity of enemies) {
      const mesh = this.entityMeshes.get(entity);
      if (!mesh || !mesh.visible) continue;
      mesh.rotation.y = Math.atan2(player.x - entity.x, player.y - entity.y);
      const bob = Math.sin(time * 5 + entity.x * .01) * (entity.type === 'wraith' ? 1.6 : .45);
      mesh.position.y = Math.max(0, bob);
      if (entity.hit > 0) mesh.traverse(object => { if (object.isMesh && object.material.emissive) object.material.emissive.set('#6b3027'); });
    }

    this.syncEntities(loot, this.lootMeshes, this.makeLoot, item => !item.got);
