382:   syncEntities(entities, cache, factory, visible) {
383:     const active = new Set();
384:     for (const entity of entities) {
385:       if (!visible(entity)) continue;
386:       active.add(entity);
387:       let mesh = cache.get(entity);
388:       if (!mesh) { mesh = factory.call(this, entity); cache.set(entity, mesh); }
389:       mesh.visible = true;
390:       mesh.position.set(entity.x, 0, entity.y);
391:     }
392:     for (const [entity, mesh] of cache) mesh.visible = active.has(entity);
393:   }
