397:     const time = elapsed || 0;
398:     this.player.position.set(player.x, Math.sin(time * 7) * .35, player.y);
399:     this.player.rotation.y = Math.PI / 2 - player.face;
400:     this.player.visible = player.invuln <= 0 || Math.floor(time * 18) % 2 === 0;
401:     this.player.rotation.z = -(player.attack > 0 ? Math.sin((player.attack / .31) * Math.PI) : 0) * .22;
402: 
403:     this.syncEntities(enemies, this.entityMeshes, this.makeEnemy, entity => entity.alive);
404:     for (const entity of enemies) {
405:       const mesh = this.entityMeshes.get(entity);
406:       if (!mesh || !mesh.visible) continue;
407:       mesh.rotation.y = Math.atan2(player.x - entity.x, player.y - entity.y);
408:       mesh.position.y = Math.max(0, Math.sin(time * 5 + entity.x * .01) * (entity.type === 'wraith' ? 1.6 : .45));
409:       mesh.traverse(object => {
410:         if (object.isMesh && object.material.emissive) object.material.emissive.set(entity.hit > 0 ? '#6b3027' : '#000000');
411:       });
412:     }
413: 
414:     this.syncEntities(loot, this.lootMeshes, this.makeLoot, item => !item.got);
415:     for (const [item, mesh] of this.lootMeshes) {
416:       if (!mesh.visible) continue;
417:       mesh.position.set(item.x, Math.sin(time * 2.3 + item.glow) * 1.4, item.y);
418:       mesh.rotation.y = time * .8 + item.glow;
419:       mesh.children[0].rotation.y = time * 1.7;
420:     }
421: 
422:     this.syncEntities(shots, this.shotMeshes, this.makeShot, shot => shot.life > 0);
423:     for (const [shot, mesh] of this.shotMeshes) {
424:       if (!shots.includes(shot)) {
425:         this.scene.remove(mesh);
426:         mesh.geometry.dispose();
427:         mesh.material.dispose();
428:         this.shotMeshes.delete(shot);
429:       } else if (mesh.visible) mesh.position.set(shot.x, 7 + Math.sin(time * 12) * 1.5, shot.y);
430:     }
431: 
432:     while (this.particleMeshes.length < particles.length) this.particleMeshes.push(this.makeParticle(particles[this.particleMeshes.length]));
433:     for (let i = 0; i < this.particleMeshes.length; i++) {
434:       const mesh = this.particleMeshes[i], particle = particles[i];
435:       mesh.visible = !!particle;
436:       if (particle) {
437:         mesh.position.set(particle.x, 2 + particle.size, particle.y);
438:         mesh.material.opacity = Math.max(0, particle.life / particle.max);
439:         mesh.scale.setScalar(.6 + particle.life / particle.max);
440:       }
441:     }
442: 
443:     const distance = Math.min(115, Math.max(72, Math.min(window.innerWidth, window.innerHeight) * .105));
444:     const target = this.cameraTarget.set(player.x, 0, player.y);
445:     const desired = new THREE.Vector3(player.x, distance * .78, player.y + distance * .92);
446:     this.camera.position.lerp(desired, 1 - Math.exp(-7 * (dt || 0)));
447:     this.camera.lookAt(target);
448:     if (shake > 0) this.camera.position.x += Math.sin(time * 83) * shake * .45;
449:     if (this.shrineCrystal) {
450:       this.shrineCrystal.rotation.y = time * .7;
451:       this.shrineCrystal.position.y = 11 + Math.sin(time * 2) * 1.2;
452:     }
453:     this.renderer.render(this.scene, this.camera);
454:   }
