169:   buildForest(trees) {
170:     if (!trees.length) return;
171:     const trunkGeo = new THREE.CylinderGeometry(.55, 1.1, 7, 6, 1);
172:     const crownGeo = new THREE.IcosahedronGeometry(1, 1);
173:     const trunk = new THREE.InstancedMesh(trunkGeo, this.materials.trunk, trees.length);
174:     const crowns = this.materials.leaf.map((material, i) => new THREE.InstancedMesh(crownGeo, material, trees.length * (i === 0 ? 2 : 1)));
175:     const colors = ['#344d32', '#415b39', '#4b6340', '#293f2c'].map(value => new THREE.Color(value));
176:     const rand = seeded(841);
177:     let crownCounts = [0, 0, 0, 0];
178: 
179:     trees.forEach((tree, i) => {
180:       const scale = tree.r / 25;
181:       this.dummy.position.set(tree.x, 3.45 * tree.h, tree.y); this.dummy.rotation.set(0, tree.seed, 0); this.dummy.scale.set(scale, tree.h, scale); this.dummy.updateMatrix(); trunk.setMatrixAt(i, this.dummy.matrix);
182:       const colorIndex = Math.floor(tree.tone * colors.length);
183:       for (let layer = 0; layer < 3; layer++) {
184:         const slot = layer === 0 ? colorIndex : (colorIndex + layer) % crowns.length;
185:         const mesh = crowns[slot], index = crownCounts[slot]++;
186:         const size = (layer === 0 ? 1 : .68) * scale;
187:         const y = (layer === 0 ? 10 : layer === 1 ? 14.2 : 8.2) * tree.h;
188:         this.dummy.position.set(tree.x + (layer === 1 ? Math.cos(tree.seed) * tree.r * .2 : 0), y, tree.y + (layer === 1 ? Math.sin(tree.seed) * tree.r * .2 : 0));
189:         this.dummy.rotation.set(rand() * .2, tree.seed + layer * 1.7, rand() * .2);
190:         this.dummy.scale.set(tree.r * .78 * size, tree.r * .72 * size, tree.r * .72 * size);
191:         this.dummy.updateMatrix(); mesh.setMatrixAt(index, this.dummy.matrix); mesh.setColorAt(index, colors[colorIndex]);
192:       }
193:     });
194:     trunk.instanceMatrix.needsUpdate = true;
195:     trunk.castShadow = false; trunk.receiveShadow = true;
196:     this.scene.add(trunk);
197:     crowns.forEach(mesh => { mesh.count = crownCounts[crowns.indexOf(mesh)]; mesh.instanceMatrix.needsUpdate = true; if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true; this.scene.add(mesh); });
