199:     // Low fern clusters break up the forest floor without adding hundreds of draw calls.
200:     const fernGeo = new THREE.ConeGeometry(1, 1, 4);
201:     const fernMesh = new THREE.InstancedMesh(fernGeo, this.materials.grass, 260);
202:     const fernRand = seeded(2089);
