205:       this.dummy.position.set(x, .55, z); this.dummy.rotation.set(0, fernRand() * TAU, 0); this.dummy.scale.set(.6 + fernRand(), 1 + fernRand() * 1.4, .6 + fernRand()); this.dummy.updateMatrix(); fernMesh.setMatrixAt(i, this.dummy.matrix);
206:     }
207:     fernMesh.instanceMatrix.needsUpdate = true; this.scene.add(fernMesh);
