47: function ribbon(points, width, material, y = .015) {
48:   const positions = [], indices = [];
49:   for (let i = 0; i < points.length; i++) {
50:     const prev = points[Math.max(0, i - 1)], next = points[Math.min(points.length - 1, i + 1)];
51:     const dx = next[0] - prev[0], dz = next[1] - prev[1];
52:     const length = Math.hypot(dx, dz) || 1;
53:     const ox = -dz / length * width / 2, oz = dx / length * width / 2;
54:     positions.push(points[i][0] + ox, y, points[i][1] + oz, points[i][0] - ox, y, points[i][1] - oz);
55:     if (i < points.length - 1) {
56:       const a = i * 2;
57:       indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
58:     }
59:   }
60:   const geometry = new THREE.BufferGeometry();
61:   geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
62:   geometry.setIndex(indices);
63:   geometry.computeVertexNormals();
64:   return new THREE.Mesh(geometry, material);
65: }
