52: function ribbon(points, width, material, y = .015) {
53:   const positions = [], indices = [];
54:   for (let i = 0; i < points.length; i++) {
55:     const prev = points[Math.max(0, i - 1)], next = points[Math.min(points.length - 1, i + 1)];
56:     const dx = next[0] - prev[0], dz = next[1] - prev[1];
57:     const length = Math.hypot(dx, dz) || 1;
58:     const ox = -dz / length * width / 2, oz = dx / length * width / 2;
59:     positions.push(points[i][0] + ox, y, points[i][1] + oz, points[i][0] - ox, y, points[i][1] - oz);
60:     if (i < points.length - 1) {
61:       const a = i * 2;
62:       indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
63:     }
64:   }
65:   const geometry = new THREE.BufferGeometry();
66:   geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
67:   geometry.setIndex(indices);
68:   geometry.computeVertexNormals();
69:   return new THREE.Mesh(geometry, material);
